var import_obsidian = require("obsidian");
async function renameVaultResource(app, from, requestedName, openNotebooks, createEngine) {
  const source = app.vault.getAbstractFileByPath(from);
  if (!(source instanceof import_obsidian.TFile))
    throw Error("No se encuentra el archivo del recurso en el Vault.");
  let name = requestedName.trim();
  if (!name || /[\\/:*?"<>|\x00-\x1f]/.test(name) || /[. ]$/.test(name))
    throw Error(
      "Escribe un nombre de archivo v\xE1lido, sin separadores de carpeta."
    );
  const extension = "." + source.extension;
  if (!name.toLowerCase().endsWith(extension.toLowerCase())) {
    if (/\.(pdf|png|jpe?g|webp|md|txt)$/i.test(name))
      throw Error("Conserva la extensi\xF3n " + extension + " del recurso.");
    name += extension;
  }
  if ([...name].length > 120)
    throw Error("El nombre del archivo debe tener como m\xE1ximo 120 caracteres.");
  const slash = from.lastIndexOf("/");
  const to2 = (slash < 0 ? "" : from.slice(0, slash + 1)) + name;
  if (to2 === from) return to2;
  const existing = app.vault.getAbstractFileByPath(to2);
  if (existing && existing !== source)
    throw Error(
      "Ya existe un archivo con ese nombre en la carpeta del recurso."
    );
  const relocate = JSON.stringify({ action: "relocate", from, to: to2, name });
  const plans = [];
  for (const file of app.vault.getFiles()) {
    if (file.extension !== "era") continue;
    const before = await app.vault.read(file);
    let resources;
    try {
      resources = JSON.parse(before).resources ?? [];
    } catch {
      continue;
    }
    if (!Array.isArray(resources) || !resources.some((r) => r && r.path === from))
      continue;
    const engine = createEngine();
    try {
      engine.load(before);
      engine.resource_command(relocate);
      plans.push({ file, before, after: engine.serialize() });
    } finally {
      engine.free();
    }
  }
  const attempted = [];
  try {
    if (source.path !== from)
      throw Error(
        "El recurso cambi\xF3 de ubicaci\xF3n. Vuelve a abrir sus opciones."
      );
    const updateClosed = async (plan, rebase = false) => {
      if (openNotebooks().has(plan.file.path)) return;
      await app.vault.process(plan.file, (current) => {
        if (openNotebooks().has(plan.file.path)) return current;
        if (!rebase && current !== plan.before)
          throw Error(
            "Un cuaderno cambi\xF3 durante el renombrado. Int\xE9ntalo de nuevo."
          );
        let after = plan.after;
        if (rebase && current !== plan.before) {
          const engine = createEngine();
          try {
            engine.load(current);
            if (!engine.resource_command(relocate)) return current;
            after = engine.serialize();
          } finally {
            engine.free();
          }
        }
        attempted.push({ file: plan.file, before: current, after });
        return after;
      });
    };
    for (const plan of plans) await updateClosed(plan);
    await app.fileManager.renameFile(source, to2);
    for (const plan of plans)
      if (!attempted.some((saved) => saved.file === plan.file))
        await updateClosed(plan, true);
    return to2;
  } catch (error) {
    const failures = [];
    if (source.path === to2) {
      try {
        await app.fileManager.renameFile(source, from);
      } catch (rollback) {
        failures.push(rollback);
      }
    }
    if (source.path === from)
      for (const plan of attempted.reverse()) {
        try {
          await app.vault.process(
            plan.file,
            (current) => current === plan.after ? plan.before : current
          );
        } catch (rollback) {
          failures.push(rollback);
        }
      }
    if (failures.length)
      throw Error(
        "No se pudo completar ni restaurar el renombrado. Revisa el archivo del recurso y sus referencias antes de reintentar.",
        { cause: error }
      );
    throw error;
  }
}

